from taf.sbts.oam.sc.rest.schemas.base import SchemaField, SchemaObject


class HwConnectorTOPOLGYV1(SchemaObject):
    dst_uid = SchemaField(name="dst_uid", not_null=True)
    label = SchemaField(name="label", not_null=False)

    def __init__(self, dst_uid=None, label=None):
        self.dst_uid = dst_uid
        self.label = label

        super(HwConnectorTOPOLGYV1, self).__init__()


class HwConnectionsTOPOLGYV1(SchemaObject):
    type = SchemaField(name="type", not_null=True)
    connectors = SchemaField(name="connectors", klass=HwConnectorTOPOLGYV1, many=True, not_null=True)

    def __init__(self, type=None, connectors=None):
        self.type = type
        self.connectors = connectors

        super(HwConnectionsTOPOLGYV1, self).__init__()
